import sys
from collections import Counter

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        arr = []
        for _ in range(n):
            arr.append(int(next(iterator)))
    except StopIteration:
        return

    freq_map = Counter(arr)

    result = []
    stack = []

    for i in range(n - 1, -1, -1):
        current_val = arr[i]
        current_freq = freq_map[current_val]

        while stack:
            top_val = stack[-1]
            top_freq = freq_map[top_val]

            if top_freq > current_freq:
                break
            else:
                stack.pop()

        if stack:
            result.append(stack[-1])
        else:
            result.append(-1)

        stack.append(current_val)

    result.reverse()
    print(*(result))

if __name__ == "__main__":
    solve()
